//! Runtime support for Rust inverse kinematics solvers generated by yaik.
//!
//! Single-file counterpart of `yaik_cpp_common.h`. Place this file next to the generated
//! `*_ik_generated.rs` files and declare them as sibling modules:
//!
//! ```ignore
//! mod yaik_rust_common;
//! mod puma_ik_generated;
//! ```
//!
//! The generated solvers import it as `super::yaik_rust_common`.
//!
//! Required dependencies in the host crate's Cargo.toml:
//!
//! ```toml
//! nalgebra = "0.35"
//! rand = "0.9"
//! glam = "0.34"
//! ```
//!
//! It provides the solution workspaces, the numerical helpers (polynomial roots, linear
//! type-2 solver, general 6-dof solver, numerical refinement) and the [`Pose4`] trait that
//! lets the generated API accept nalgebra, glam or plain-array poses.

use nalgebra::{DMatrix, DVector, Matrix4, Rotation3, SMatrix, Unit, Vector3};
use std::f64::consts::PI;

/// Indicate the value is invalid
pub const INVALID_VALUE: f64 = f64::MAX;

// ---------------------------------------------------------------------------
// Pose abstraction: nalgebra / glam / plain arrays
// ---------------------------------------------------------------------------

/// A homogeneous 4x4 transform that the generated solvers can consume and produce.
/// The solvers work internally with `nalgebra::Matrix4<f64>`.
pub trait Pose4: Sized {
    fn to_matrix4(&self) -> Matrix4<f64>;
    fn from_matrix4(m: &Matrix4<f64>) -> Self;
}

impl Pose4 for Matrix4<f64> {
    fn to_matrix4(&self) -> Matrix4<f64> {
        *self
    }
    fn from_matrix4(m: &Matrix4<f64>) -> Self {
        *m
    }
}

/// Row-major `[[f64; 4]; 4]`, i.e. `m[row][col]`.
impl Pose4 for [[f64; 4]; 4] {
    fn to_matrix4(&self) -> Matrix4<f64> {
        Matrix4::from_fn(|r, c| self[r][c])
    }
    fn from_matrix4(m: &Matrix4<f64>) -> Self {
        let mut out = [[0.0; 4]; 4];
        for (r, row) in out.iter_mut().enumerate() {
            for (c, value) in row.iter_mut().enumerate() {
                *value = m[(r, c)];
            }
        }
        out
    }
}

impl Pose4 for glam::DMat4 {
    fn to_matrix4(&self) -> Matrix4<f64> {
        // Both glam and nalgebra store matrices column-major
        Matrix4::from_column_slice(&self.to_cols_array())
    }
    fn from_matrix4(m: &Matrix4<f64>) -> Self {
        let mut cols = [0.0; 16];
        cols.copy_from_slice(m.as_slice());
        glam::DMat4::from_cols_array(&cols)
    }
}

impl Pose4 for glam::Mat4 {
    fn to_matrix4(&self) -> Matrix4<f64> {
        Matrix4::from_iterator(self.to_cols_array().iter().map(|v| *v as f64))
    }
    fn from_matrix4(m: &Matrix4<f64>) -> Self {
        let mut cols = [0.0f32; 16];
        for (dst, src) in cols.iter_mut().zip(m.as_slice()) {
            *dst = *src as f32;
        }
        glam::Mat4::from_cols_array(&cols)
    }
}

// ---------------------------------------------------------------------------
// Safe operations
// ---------------------------------------------------------------------------

pub fn safe_sqrt(a: f64) -> f64 {
    if a >= 0.0 {
        a.sqrt()
    } else {
        0.0
    }
}

pub fn safe_asin(a: f64) -> f64 {
    if a > 1.0 {
        0.5 * PI
    } else if a < -1.0 {
        -0.5 * PI
    } else {
        a.asin()
    }
}

pub fn safe_acos(a: f64) -> f64 {
    if a > 1.0 {
        0.0
    } else if a < -1.0 {
        PI
    } else {
        a.acos()
    }
}

/// Wrap an angle to [-pi, pi]. Non-finite values are returned unchanged.
pub fn wrap_angle_value_to_pi(value: f64) -> f64 {
    if !value.is_finite() || (-PI..=PI).contains(&value) {
        return value;
    }
    let wrapped = (value + PI).rem_euclid(2.0 * PI) - PI;
    // Keep +pi for inputs that land exactly on the boundary from above, like the C++ while-loop
    if wrapped == -PI && value > 0.0 {
        PI
    } else {
        wrapped
    }
}

// ---------------------------------------------------------------------------
// Solution containers
// ---------------------------------------------------------------------------

/// Remove (near) duplicated solutions, keeping the first occurrence and the order.
pub fn remove_duplicate<const N: usize>(ik_output: &mut Vec<[f64; N]>, tolerance: f64) {
    if ik_output.len() <= 1 {
        return;
    }
    let is_duplicate =
        |a: &[f64; N], b: &[f64; N]| a.iter().zip(b.iter()).all(|(x, y)| (x - y).abs() <= tolerance);
    let mut kept: Vec<[f64; N]> = Vec::with_capacity(ik_output.len());
    for solution in ik_output.iter() {
        if !kept.iter().any(|k| is_duplicate(k, solution)) {
            kept.push(*solution);
        }
    }
    *ik_output = kept;
}

/// Fixed-size array to hold an intermediate ik solution
pub type IntermediateSolution<const N: usize> = [f64; N];

/// Construct an intermediate solution filled with invalid values
pub fn make_intermediate_solution<const N: usize>() -> IntermediateSolution<N> {
    [INVALID_VALUE; N]
}

/// A queue with fixed capacity
#[derive(Clone, Copy, Debug)]
pub struct FixedBufferQueue<T: Copy, const CAPACITY: usize> {
    elements: [T; CAPACITY],
    top_index: usize,
}

impl<T: Copy, const CAPACITY: usize> FixedBufferQueue<T, CAPACITY> {
    pub fn new(fill: T) -> Self {
        assert!(CAPACITY >= 1, "Zero capacity not allowed");
        Self { elements: [fill; CAPACITY], top_index: 0 }
    }

    pub fn reset(&mut self) {
        self.top_index = 0;
    }

    /// Push an element into the queue. Return the appended index, or None if the queue is full.
    pub fn push(&mut self, element: T) -> Option<usize> {
        if self.top_index >= CAPACITY {
            return None;
        }
        let appended_idx = self.top_index;
        self.elements[appended_idx] = element;
        self.top_index += 1;
        Some(appended_idx)
    }

    pub fn size(&self) -> usize {
        self.top_index
    }

    pub fn is_empty(&self) -> bool {
        self.top_index == 0
    }

    pub fn as_slice(&self) -> &[T] {
        &self.elements[..self.top_index]
    }
}

impl<T: Copy, const CAPACITY: usize> std::ops::Index<usize> for FixedBufferQueue<T, CAPACITY> {
    type Output = T;
    fn index(&self, index: usize) -> &T {
        &self.as_slice()[index]
    }
}

impl<T: Copy, const CAPACITY: usize> std::ops::IndexMut<usize> for FixedBufferQueue<T, CAPACITY> {
    fn index_mut(&mut self, index: usize) -> &mut T {
        let size = self.top_index;
        &mut self.elements[..size][index]
    }
}

/// The queue to hold the intermediate solutions
#[derive(Clone, Debug)]
pub struct SolutionQueue<const NQ: usize, const CAPACITY: usize> {
    pub solutions: FixedBufferQueue<IntermediateSolution<NQ>, CAPACITY>,
    pub solutions_validity: [bool; CAPACITY],
}

impl<const NQ: usize, const CAPACITY: usize> Default for SolutionQueue<NQ, CAPACITY> {
    fn default() -> Self {
        Self::new()
    }
}

impl<const NQ: usize, const CAPACITY: usize> SolutionQueue<NQ, CAPACITY> {
    pub fn new() -> Self {
        Self {
            solutions: FixedBufferQueue::new(make_intermediate_solution::<NQ>()),
            solutions_validity: [false; CAPACITY],
        }
    }

    pub fn reset(&mut self) {
        self.solutions.reset();
        self.solutions_validity.fill(false);
    }

    /// Push a solution into the queue. Return the appended index, or None if the queue is full.
    pub fn push_solution(&mut self, solution: IntermediateSolution<NQ>) -> Option<usize> {
        let appended_idx = self.solutions.push(solution);
        if let Some(idx) = appended_idx {
            self.solutions_validity[idx] = true;
        }
        appended_idx
    }

    pub fn get_solution(&self, solution_idx: usize) -> &IntermediateSolution<NQ> {
        &self.solutions[solution_idx]
    }

    pub fn get_solution_mut(&mut self, solution_idx: usize) -> &mut IntermediateSolution<NQ> {
        &mut self.solutions[solution_idx]
    }

    pub fn is_solution_valid(&self, solution_idx: usize) -> bool {
        self.solutions_validity[solution_idx]
    }

    pub fn size(&self) -> usize {
        self.solutions.size()
    }
}

/// The index workspace for different nodes
#[derive(Clone, Debug, Default)]
pub struct NodeIndexWorkspace<const MAX_N_SOLUTIONS: usize> {
    pub node_input_indices_vector: Vec<FixedBufferQueue<usize, MAX_N_SOLUTIONS>>,
    pub node_input_validity_vector: Vec<bool>,
}

impl<const MAX_N_SOLUTIONS: usize> NodeIndexWorkspace<MAX_N_SOLUTIONS> {
    pub fn new() -> Self {
        Self { node_input_indices_vector: Vec::new(), node_input_validity_vector: Vec::new() }
    }

    pub fn reset(&mut self, n_node: usize) {
        self.node_input_indices_vector.clear();
        self.node_input_indices_vector.resize(n_node, FixedBufferQueue::new(0));
        self.node_input_validity_vector.clear();
        self.node_input_validity_vector.resize(n_node, false);

        // Set the root node validity to true
        if n_node > 0 {
            self.node_input_validity_vector[0] = true;
        }
    }

    /// Add an index to a node. Return false if the node queue is full.
    pub fn append_index_to_node(&mut self, node_idx: usize, index_to_append: usize) -> bool {
        let appended = self.node_input_indices_vector[node_idx].push(index_to_append).is_some();
        if appended {
            self.node_input_validity_vector[node_idx] = true;
        }
        appended
    }

    /// Add the index of a (possibly failed) queue push to a node
    pub fn add_input_index_to(&mut self, node_idx: usize, solution_idx: Option<usize>) {
        if let Some(idx) = solution_idx {
            self.append_index_to_node(node_idx, idx);
        }
    }

    pub fn get_input_indices_for_node(&self, node_idx: usize) -> &FixedBufferQueue<usize, MAX_N_SOLUTIONS> {
        &self.node_input_indices_vector[node_idx]
    }

    pub fn is_input_indices_valid_for_node(&self, node_idx: usize) -> bool {
        self.node_input_validity_vector[node_idx]
    }

    pub fn num_nodes(&self) -> usize {
        self.node_input_indices_vector.len()
    }
}

/// A struct to hold all the buffers of the raw ik
#[derive(Clone, Debug)]
pub struct RawIkWorkspace<const INTERMEDIATE_SOLUTION_SIZE: usize, const MAX_N_SOLUTIONS: usize, const ROBOT_NQ: usize> {
    pub solution_queue: SolutionQueue<INTERMEDIATE_SOLUTION_SIZE, MAX_N_SOLUTIONS>,
    pub node_index_workspace: NodeIndexWorkspace<MAX_N_SOLUTIONS>,
    pub raw_ik_out: Vec<[f64; ROBOT_NQ]>,
}

impl<const I: usize, const M: usize, const N: usize> Default for RawIkWorkspace<I, M, N> {
    fn default() -> Self {
        Self::new()
    }
}

impl<const I: usize, const M: usize, const N: usize> RawIkWorkspace<I, M, N> {
    pub fn new() -> Self {
        Self {
            solution_queue: SolutionQueue::new(),
            node_index_workspace: NodeIndexWorkspace::new(),
            raw_ik_out: Vec::with_capacity(M),
        }
    }
}

// ---------------------------------------------------------------------------
// Polynomial solver
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct PolynomialRealRoot {
    pub is_valid: bool,
    pub value: f64,
}

/// Eigenvalues of a real square matrix, None if the Schur decomposition does not converge.
pub fn real_matrix_eigenvalues(m: DMatrix<f64>) -> Option<Vec<(f64, f64)>> {
    let schur = nalgebra::Schur::try_new(m, f64::EPSILON, 10_000)?;
    Some(schur.complex_eigenvalues().iter().map(|c| (c.re, c.im)).collect())
}

/// Real roots of the polynomial `c[0] x^n + c[1] x^(n-1) + ... + c[n]`, with n = POLY_ORDER.
pub fn compute_polynomial_real_roots<const POLY_ORDER: usize>(
    coefficient_high_to_low_order: &[f64],
) -> [PolynomialRealRoot; POLY_ORDER] {
    assert_eq!(coefficient_high_to_low_order.len(), POLY_ORDER + 1);
    let mut poly_roots = [PolynomialRealRoot::default(); POLY_ORDER];

    // Drop vanishing leading coefficients to get the actual degree
    let first_non_zero = match coefficient_high_to_low_order.iter().position(|c| *c != 0.0) {
        Some(idx) => idx,
        None => return poly_roots,
    };
    let coefficients = &coefficient_high_to_low_order[first_non_zero..];
    let degree = coefficients.len() - 1;
    if degree == 0 || coefficients.iter().any(|c| !c.is_finite()) {
        return poly_roots;
    }

    // Companion matrix of the monic polynomial
    let leading = coefficients[0];
    let mut companion = DMatrix::<f64>::zeros(degree, degree);
    for c in 0..degree {
        companion[(0, c)] = -coefficients[c + 1] / leading;
    }
    for r in 1..degree {
        companion[(r, r - 1)] = 1.0;
    }

    if let Some(eigenvalues) = real_matrix_eigenvalues(companion) {
        for (i, (re, im)) in eigenvalues.into_iter().enumerate() {
            if im.abs() < 1e-6 {
                poly_roots[i] = PolynomialRealRoot { is_valid: true, value: re };
            }
        }
    }
    poly_roots
}

// ---------------------------------------------------------------------------
// Linear type-2 solver
// ---------------------------------------------------------------------------

pub mod linear_solver {
    use super::*;

    /// Solve the 3x4 linear system on [sin(x), cos(x), sin(y), cos(y)] for y.
    pub fn try_solve_linear_type2(a_mat: &[[f64; 4]; 3]) -> Option<(f64, f64)> {
        let (a, b, c, d) = (a_mat[0][0], a_mat[0][1], a_mat[1][0], a_mat[1][1]);
        let ad_minus_bc = a * d - b * c;
        const ZERO_TOLERANCE: f64 = 1e-10;
        if ad_minus_bc.abs() < ZERO_TOLERANCE {
            return None;
        }

        // Inverse of the top 2x2 matrix
        let inv = [[d / ad_minus_bc, -b / ad_minus_bc], [-c / ad_minus_bc, a / ad_minus_bc]];

        // [sin(x), cos(x)].T = B * [sin(y), cos(y)].T
        let mut b_mat = [[0.0; 2]; 2];
        for r in 0..2 {
            for col in 0..2 {
                b_mat[r][col] = -(inv[r][0] * a_mat[0][2 + col] + inv[r][1] * a_mat[1][2 + col]);
            }
        }
        let e = a_mat[2][2] + a_mat[2][0] * b_mat[0][0] + a_mat[2][1] * b_mat[1][0];
        let f = a_mat[2][3] + a_mat[2][0] * b_mat[0][1] + a_mat[2][1] * b_mat[1][1];
        if e.abs() < ZERO_TOLERANCE && f.abs() < ZERO_TOLERANCE {
            return None;
        }

        let solution_0 = (-f).atan2(e);
        let mut solution_1 = solution_0 + PI;
        if solution_1 > PI {
            solution_1 -= 2.0 * PI;
        }
        Some((solution_0, solution_1))
    }

    pub fn try_solve_linear_type2_specific_rows<const N_ROWS: usize>(
        a_mat: &[[f64; 4]; N_ROWS],
        row_0: usize,
        row_1: usize,
        row_2: usize,
    ) -> Option<(f64, f64)> {
        try_solve_linear_type2(&[a_mat[row_0], a_mat[row_1], a_mat[row_2]])
    }
}

// ---------------------------------------------------------------------------
// General 6-dof solver
// ---------------------------------------------------------------------------

pub mod general_6dof_internal {
    use super::*;

    pub fn all_finite(m: &DMatrix<f64>) -> bool {
        m.iter().all(|v| v.is_finite())
    }

    /// Returns (tau_sin, tau_cos, tau_const), or None if the reduction matrix is singular
    pub fn numerical_reduce(
        a_sin: &DMatrix<f64>,
        a_cos: &DMatrix<f64>,
        c_const: &DMatrix<f64>,
        rhs_matrix: &DMatrix<f64>,
        lines_to_reduce: &[usize],
        remaining_lines: &[usize],
    ) -> Option<(DMatrix<f64>, DMatrix<f64>, DMatrix<f64>)> {
        let r_l = rhs_matrix.select_rows(lines_to_reduce);
        let r_u = rhs_matrix.select_rows(remaining_lines);
        let inv_r_l = r_l.try_inverse()?;
        if !all_finite(&inv_r_l) {
            return None;
        }
        let r_u_dot_r_l_inv = r_u * inv_r_l;
        let reduce = |m: &DMatrix<f64>| m.select_rows(remaining_lines) - &r_u_dot_r_l_inv * m.select_rows(lines_to_reduce);
        Some((reduce(a_sin), reduce(a_cos), reduce(c_const)))
    }

    pub fn sincos_coefficient_to_tanhalf_coefficient(a: &DMatrix<f64>) -> DMatrix<f64> {
        assert_eq!(a.ncols(), 9);
        let col = |i: usize| a.column(i).into_owned();
        let mut out = DMatrix::<f64>::zeros(a.nrows(), 9);
        out.set_column(0, &(col(3) - col(5) - col(7) + col(8)));
        out.set_column(1, &((col(2) - col(6)) * -2.0));
        out.set_column(2, &(-col(3) - col(5) + col(7) + col(8)));
        out.set_column(3, &((col(1) - col(4)) * -2.0));
        out.set_column(4, &(col(0) * 4.0));
        out.set_column(5, &((col(1) + col(4)) * 2.0));
        out.set_column(6, &(-col(3) + col(5) - col(7) + col(8)));
        out.set_column(7, &((col(2) + col(6)) * 2.0));
        out.set_column(8, &(col(3) + col(5) + col(7) + col(8)));
        out
    }

    /// Solve (A x^2 + B x + C) v = 0 with 6x9 coefficient matrices, x = tan(theta/2)
    pub fn compute_solution_from_tanhalf_lme(
        a_x2: &DMatrix<f64>,
        b_x: &DMatrix<f64>,
        c: &DMatrix<f64>,
        solution_buffer: &mut [f64; 16],
    ) -> usize {
        let expand = |m: &DMatrix<f64>| {
            let mut out = DMatrix::<f64>::zeros(12, 12);
            out.view_mut((0, 0), (6, 9)).copy_from(m);
            out.view_mut((6, 3), (6, 9)).copy_from(m);
            out
        };
        let a_inv = match expand(a_x2).try_inverse() {
            Some(inv) if all_finite(&inv) => inv,
            _ => return 0,
        };
        let b_12 = expand(b_x);
        let c_12 = expand(c);

        let mut m = DMatrix::<f64>::zeros(24, 24);
        m.view_mut((0, 12), (12, 12)).fill_with_identity();
        m.view_mut((12, 0), (12, 12)).copy_from(&(-(&a_inv * c_12)));
        m.view_mut((12, 12), (12, 12)).copy_from(&(-(&a_inv * b_12)));

        let eigenvalues = match real_matrix_eigenvalues(m) {
            Some(values) => values,
            None => return 0,
        };
        let mut solution_counter = 0;
        for (re, im) in eigenvalues {
            if im.abs() < 1e-6 && solution_counter < solution_buffer.len() {
                solution_buffer[solution_counter] = 2.0 * re.atan();
                solution_counter += 1;
            }
        }
        solution_counter
    }

    /// Returns (A, B, C) of the tan-half linear matrix equation
    pub fn sincos_lme_to_tanhalf_lme(
        a_sin: &DMatrix<f64>,
        a_cos: &DMatrix<f64>,
        c_const: &DMatrix<f64>,
    ) -> (DMatrix<f64>, DMatrix<f64>, DMatrix<f64>) {
        (c_const - a_cos, a_sin * 2.0, c_const + a_cos)
    }
}

pub fn general_6dof_numerical_reduce_solve(
    a_sin: &DMatrix<f64>,
    a_cos: &DMatrix<f64>,
    c_const: &DMatrix<f64>,
    rhs_matrix: &DMatrix<f64>,
    lines_to_reduce: &[usize],
    remaining_lines: &[usize],
    solution_buffer: &mut [f64; 16],
) -> usize {
    use general_6dof_internal::*;
    let (tau_sin, tau_cos, tau_const) =
        match numerical_reduce(a_sin, a_cos, c_const, rhs_matrix, lines_to_reduce, remaining_lines) {
            Some(reduced) => reduced,
            None => return 0,
        };
    let tau_sin = sincos_coefficient_to_tanhalf_coefficient(&tau_sin);
    let tau_cos = sincos_coefficient_to_tanhalf_coefficient(&tau_cos);
    let tau_const = sincos_coefficient_to_tanhalf_coefficient(&tau_const);
    let (a, b, c) = sincos_lme_to_tanhalf_lme(&tau_sin, &tau_cos, &tau_const);
    compute_solution_from_tanhalf_lme(&a, &b, &c, solution_buffer)
}

// ---------------------------------------------------------------------------
// Transform utilities and numerical refinement
// ---------------------------------------------------------------------------

pub fn inverse_transform(transform: &Matrix4<f64>) -> Matrix4<f64> {
    let rotation_t = transform.fixed_view::<3, 3>(0, 0).transpose();
    let translation = -(rotation_t * transform.fixed_view::<3, 1>(0, 3));
    let mut inv = Matrix4::identity();
    inv.fixed_view_mut::<3, 3>(0, 0).copy_from(&rotation_t);
    inv.fixed_view_mut::<3, 1>(0, 3).copy_from(&translation);
    inv
}

pub fn disturb_transform(transform: &Matrix4<f64>) -> Matrix4<f64> {
    disturb_transform_with(transform, 1e-2, 1e-2)
}

pub fn disturb_transform_with(transform: &Matrix4<f64>, disturb_angle: f64, disturb_translation: f64) -> Matrix4<f64> {
    let mut axis = Vector3::from_fn(|_, _| rand::random_range(-1.0..=1.0));
    if axis.norm_squared() < 1e-4 {
        axis[0] += 0.1;
    }
    let rotation = Rotation3::from_axis_angle(&Unit::new_normalize(axis), disturb_angle);
    let mut disturb_matrix = Matrix4::identity();
    disturb_matrix.fixed_view_mut::<3, 3>(0, 0).copy_from(rotation.matrix());
    for i in 0..3 {
        disturb_matrix[(i, 3)] -= disturb_translation;
    }
    disturb_matrix * transform
}

/// Damped Gauss-Newton refinement of `q` towards `ee_target`
pub fn numerical_refinement<const ROBOT_NQ: usize>(
    fk_functor: impl Fn(&[f64; ROBOT_NQ]) -> Matrix4<f64>,
    twist_jacobian_functor: impl Fn(&[f64; ROBOT_NQ], &mut SMatrix<f64, 6, ROBOT_NQ>),
    ee_target: &Matrix4<f64>,
    q: &mut [f64; ROBOT_NQ],
) {
    numerical_refinement_with(fk_functor, twist_jacobian_functor, ee_target, q, 1e-4)
}

pub fn numerical_refinement_with<const ROBOT_NQ: usize>(
    fk_functor: impl Fn(&[f64; ROBOT_NQ]) -> Matrix4<f64>,
    twist_jacobian_functor: impl Fn(&[f64; ROBOT_NQ], &mut SMatrix<f64, 6, ROBOT_NQ>),
    ee_target: &Matrix4<f64>,
    q: &mut [f64; ROBOT_NQ],
    diagonal_damping: f64,
) {
    let mut jacobian = SMatrix::<f64, 6, ROBOT_NQ>::zeros();
    const N_ITERATIONS: usize = 10;
    for _ in 0..N_ITERATIONS {
        let ee_pose_i = fk_functor(q);
        let t = ee_target * inverse_transform(&ee_pose_i);
        let twist_target = DVector::from_column_slice(&[
            0.5 * (t[(2, 1)] - t[(1, 2)]),
            0.5 * (t[(0, 2)] - t[(2, 0)]),
            0.5 * (t[(1, 0)] - t[(0, 1)]),
            t[(0, 3)],
            t[(1, 3)],
            t[(2, 3)],
        ]);

        twist_jacobian_functor(q, &mut jacobian);
        let j = DMatrix::from_column_slice(6, ROBOT_NQ, jacobian.as_slice());
        let mut jtj = j.transpose() * &j;
        let jte = j.transpose() * twist_target;
        for k in 0..ROBOT_NQ {
            jtj[(k, k)] += diagonal_damping;
        }

        if let Some(delta_q) = jtj.col_piv_qr().solve(&jte) {
            for k in 0..ROBOT_NQ {
                q[k] += delta_q[k];
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn polynomial_roots() {
        // (x - 1)(x + 2)(x - 3) = x^3 - 2x^2 - 5x + 6
        let roots = compute_polynomial_real_roots::<3>(&[1.0, -2.0, -5.0, 6.0]);
        let mut values: Vec<f64> = roots.iter().filter(|r| r.is_valid).map(|r| r.value).collect();
        values.sort_by(|a, b| a.partial_cmp(b).unwrap());
        assert_eq!(values.len(), 3);
        for (v, e) in values.iter().zip([-2.0, 1.0, 3.0]) {
            assert!((v - e).abs() < 1e-9);
        }
        // Leading zero coefficient: 0 x^2 + x - 1
        let roots = compute_polynomial_real_roots::<2>(&[0.0, 1.0, -1.0]);
        assert!(roots[0].is_valid && (roots[0].value - 1.0).abs() < 1e-12 && !roots[1].is_valid);
    }

    #[test]
    fn remove_duplicate_keeps_order() {
        let mut v = vec![[0.0, 1.0], [0.0, 1.0 + 1e-9], [2.0, 3.0], [0.0, 1.0]];
        remove_duplicate(&mut v, 1e-6);
        assert_eq!(v, vec![[0.0, 1.0], [2.0, 3.0]]);
    }

    #[test]
    fn inverse_transform_roundtrip() {
        let t = disturb_transform_with(&Matrix4::identity(), 0.7, 0.3);
        let err = (t * inverse_transform(&t) - Matrix4::identity()).norm();
        assert!(err < 1e-12);
    }

    #[test]
    fn pose_array_roundtrip() {
        let t = disturb_transform_with(&Matrix4::identity(), 0.4, 0.2);
        let arr = <[[f64; 4]; 4]>::from_matrix4(&t);
        assert_eq!(arr[0][3], t[(0, 3)]);
        assert_eq!(arr.to_matrix4(), t);
    }

        #[test]
    fn pose_glam_roundtrip() {
        let t = disturb_transform_with(&Matrix4::identity(), 0.4, 0.2);
        let g = glam::DMat4::from_matrix4(&t);
        assert_eq!(g.col(3)[0], t[(0, 3)]);
        assert_eq!(g.to_matrix4(), t);
    }
}
